def multistart(fn, starts: list, bounds: list) -> dict:
    """Run minimize from every start; keep the best."""
    best, n_local = None, 0
    for x0 in starts:
        res = minimize(fn, x0=x0, bounds=bounds)
        value = round(res.fun, 4)
        if value > -9:
            n_local += 1
        if best is None or value < best['value']:
            best = {'start': x0, 'value': value,
                    'x': res.x.round(4)}
    print('LOCAL trap:', n_local, 'of', len(starts))
    return best
